<?php
declare(strict_types=1);
namespace App\Repositories\Admin;
use PDO;
final class FebAdminRepository {
 public function __construct(private PDO $pdo){}
 public function pdo():PDO{return $this->pdo;}
 public function workflows():array{return $this->pdo->query("SELECT w.*,COUNT(DISTINCT r.id) usage_count,COUNT(DISTINCT s.id) step_count FROM feb_workflows w LEFT JOIN feb_workflow_steps s ON s.workflow_id=w.id LEFT JOIN feb_requests r ON r.workflow_id=w.id GROUP BY w.id ORDER BY w.id")->fetchAll();}
 public function workflow(int $id,bool $lock=false):?array{$q=$this->pdo->prepare('SELECT w.*,(SELECT COUNT(*) FROM feb_requests r WHERE r.workflow_id=w.id) usage_count FROM feb_workflows w WHERE w.id=?'.($lock?' FOR UPDATE':''));$q->execute([$id]);$w=$q->fetch();if(!$w)return null;$q=$this->pdo->prepare('SELECT * FROM feb_workflow_steps WHERE workflow_id=? ORDER BY step_order,id');$q->execute([$id]);$w['steps']=$q->fetchAll();return $w;}
 public function users():array{return $this->pdo->query("SELECT id,full_name,email,is_admin,status FROM users WHERE status='active' ORDER BY full_name")->fetchAll();}
 public function chantiers():array{return $this->pdo->query("SELECT s.id,s.code,s.nom,p.intitule,cb.budget_id FROM btp_chantier_starts s JOIN btp_projets p ON p.id=s.projet_id LEFT JOIN feb_chantier_budgets cb ON cb.chantier_id=s.id ORDER BY s.nom")->fetchAll();}
 public function accesses():array{return $this->pdo->query("SELECT a.*,u.full_name,u.email,s.code,s.nom,g.full_name granted_by_name FROM feb_chantier_access a JOIN users u ON u.id=a.user_id JOIN users g ON g.id=a.granted_by JOIN btp_chantier_starts s ON s.id=a.chantier_id ORDER BY s.nom,u.full_name,a.access_role")->fetchAll();}
 public function assignmentsFor(int $chantier,int $user,bool $lock=false):array{$q=$this->pdo->prepare('SELECT * FROM feb_chantier_access WHERE chantier_id=? AND user_id=? ORDER BY access_role'.($lock?' FOR UPDATE':''));$q->execute([$chantier,$user]);return $q->fetchAll();}
 public function budgets():array{return $this->pdo->query("SELECT cb.*,s.code,s.nom,b.revision,b.total_cost,b.status,u.full_name assigned_by_name,(SELECT COUNT(*) FROM feb_requests r WHERE r.chantier_id=cb.chantier_id) usage_count FROM feb_chantier_budgets cb JOIN btp_chantier_starts s ON s.id=cb.chantier_id JOIN btp_prestart_budgets b ON b.id=cb.budget_id JOIN users u ON u.id=cb.assigned_by ORDER BY s.nom")->fetchAll();}
 public function eligibleBudgets(int $chantier):array{$q=$this->pdo->prepare("SELECT b.id,b.revision,b.total_cost,b.status,bc.reference FROM btp_chantier_starts s JOIN btp_client_orders bc ON bc.projet_id=s.projet_id JOIN btp_prestart_budgets b ON b.order_id=bc.id WHERE s.id=? AND b.status='valide' ORDER BY b.revision DESC,b.id DESC");$q->execute([$chantier]);return $q->fetchAll();}
 public function officeServices():array{return $this->pdo->query("SELECT id,name FROM rh_services WHERE is_active=1 ORDER BY name")->fetchAll()?:[];}
 public function officeAllocations():array{return $this->pdo->query("SELECT a.*,s.name service_name FROM feb_office_budget_allocations a JOIN rh_services s ON s.id=a.service_id ORDER BY a.fiscal_year DESC,s.name,a.label")->fetchAll()?:[];}
 public function history():array{return $this->pdo->query("SELECT h.*,u.full_name actor_name FROM feb_admin_history h JOIN users u ON u.id=h.actor_id ORDER BY h.id DESC LIMIT 300")->fetchAll();}
 public function userCanFebAction(int $user,string $action):bool{$column=match($action){'view'=>'can_view','create'=>'can_create','update'=>'can_update','delete'=>'can_delete',default=>null};if(!$column)return false;$q=$this->pdo->prepare("SELECT u.is_admin OR COALESCE(p.$column,0) FROM users u LEFT JOIN permission_entities e ON e.code='feb_requests' LEFT JOIN user_permissions p ON p.user_id=u.id AND p.entity_id=e.id WHERE u.id=? AND u.status='active'");$q->execute([$user]);return (bool)$q->fetchColumn();}
 public function log(int $actor,string $type,?int $id,string $action,mixed $before,mixed $after):void{$q=$this->pdo->prepare('INSERT INTO feb_admin_history(actor_id,entity_type,entity_id,action,before_json,after_json) VALUES(?,?,?,?,?,?)');$q->execute([$actor,$type,$id,$action,$before===null?null:json_encode($before,JSON_UNESCAPED_UNICODE),$after===null?null:json_encode($after,JSON_UNESCAPED_UNICODE)]);}
}
